def normalise_phone(s) -> str | None:
    s = s.strip()
    if not s:
        return None

    if s.startswith("+44"):
        if len(s) == 13 and s[3:].isdigit() and len(s[3:]) == 10:
            return s
        return None

    if s.startswith("+1"):
        if len(s) == 12 and s[2:].isdigit() and len(s[2:]) == 10:
            return s
        return None

    s = s.replace(" ", "")

    if len(s) == 11 and s[0] == '0' and s[1:].isdigit():
        return "+44" + s[1:]

    if len(s) == 10 and s.isdigit():
        return "+1" + s

    return None


def test_normalise_phone():
    assert normalise_phone("07123 456 789") == "+447123456789"
    assert normalise_phone("01234 567 890") == "+441234567890"
    assert normalise_phone("1234567890") == "+11234567890"
    assert normalise_phone("+441234567890") == "+441234567890"
    assert normalise_phone("+11234567890") == "+11234567890"
    assert normalise_phone("07123 456 7890") is None
    assert normalise_phone("+4412345678901") is None
    assert normalise_phone("12345") is None
    assert normalise_phone("") is None
    assert normalise_phone("   ") is None
    assert normalise_phone("invalid number") is None
